<div class="space-y-6"><x-ui.breadcrumbs :items="[['label' => 'Exams', 'url' => route('student.exams', $school)], ['label' => 'Attempt']]" /><x-ui.page-header :title="$attempt->exam?->name.' attempt'" description="Questions and expiry are server-snapshotted. Your browser is not the timing authority." /><x-ui.snapshot-card :title="'Attempt status: '.ucfirst($attempt->status)" :status="$attempt->status" :meta="'Server expiry: '.$attempt->expires_at">@if($message)<x-ui.alert type="success">{{ $message }}</x-ui.alert>@endif</x-ui.snapshot-card>@forelse($attempt->questions as $q)<x-ui.card :title="'Question '.$q->sort_order" :subtitle="$q->marks.' marks'"><p class="mb-4 whitespace-pre-line">{{ $q->question_text }}</p>@if($attempt->isActive() && now()->lt($attempt->expires_at))<x-ui.input :label="'Answer for question '.$q->sort_order" wire:model="answers.{{ $q->id }}" /><div class="mt-3"><x-ui.button variant="secondary" wire:click="saveAnswer({{ $q->id }}, $wire.answers[{{ $q->id }}])" loading="saveAnswer">Save answer</x-ui.button></div>@else<x-ui.alert type="warning">This attempt is submitted, expired, or otherwise read-only.</x-ui.alert>@endif</x-ui.card>@empty<x-ui.empty-state title="No snapshot questions" message="This attempt has no available paper snapshot." />@endforelse @if($attempt->isActive() && now()->lt($attempt->expires_at))<x-ui.confirm-dialog title="Submit attempt?" message="Submission is final under the existing examination lifecycle." confirm-label="Submit attempt" event="submit">Submit attempt</x-ui.confirm-dialog>@endif</div>
